TOPIC = "[TOPIC]"

class PorcelainChronicleEngine:
    def __init__(self, topic):
        self.topic = topic

        self.chapters = infer_four_chapters(
            topic,
            criteria=[
                "topic relevance",
                "visual distinctiveness",
                "narrative variety",
                "diorama potential",
                "recognizability"
            ]
        )

        self.material = infer_unifying_ceramic_language(topic)
        self.ornament = infer_topic_specific_ornament_system(topic)

    def build_chapter(self, chapter):
        return {
            "hero": infer_primary_subject(chapter),
            "actors": infer_supporting_actors(chapter),
            "environment": infer_scene_environment(chapter),
            "action": infer_key_action(chapter),
            "props": infer_topic_props(chapter),
            "background": infer_depth_elements(chapter),
            "label": derive_short_scene_title(chapter),
            "secondary_label": infer_date_era_metric_or_subtitle(chapter)
        }

    def ceramicize(self, scene):
        return convert_scene_materials(
            scene,
            base_material="fine glazed porcelain",
            color_system="ivory + cobalt dominant",
            surface_detail=[
                "hand-painted motifs",
                "fine crackle glaze",
                "ceramic seams",
                "glossy highlights",
                "sculpted relief"
            ],
            ornament=self.ornament
        )

    def display_base(self, scene):
        return {
            "base": "museum-grade ceramic plinth",
            "plaque": scene["label"],
            "secondary_text": scene["secondary_label"]
        }

    def render(self):
        panels = []

        for chapter in self.chapters:
            scene = self. build_chapter(chapter)
            panels.append({
                "scene": self.ceramicize(scene),
                "base": self.display_base(scene)
            })

        return render_grid(
            panels=panels,
            layout="2x2",
            background="dark gallery neutral",
            camera="macro collectible photography",
            lighting="dramatic museum display"
        )

